 function apply(){if(composing||!dirty()||state.kind!==state.mode)return;let p=parseDraft();if(p.error)return;pushHistory();if(state.mode==='lyrics'){p.items.forEach((w,i)=>model.lyrics[state.verse][state.target+i]=w);}else{let end=state.target+p.total;model.events=model.events.filter(e=>e.start<state.target-1e-6||e.start>=end-1e-6);p.items.forEach((e,i)=>model.events.push({...clone(e),id:'edited-'+model.commands+'-'+i}));model.events.sort((a,b)=>a.start-b.start);state.kind='numbered';state.member=0;}
 state.base=state.draft;state.baseTemplate=state.template;immediateMessage='';commit(state.mode==='lyrics'?'歌词已应用 · 停留当前位置':'简谱已替换 · 停留当前位置');}
